*******************************************************************************
* v3copy.asm -- video3's copy engine on the host emulator.  GENERATED by
* bench/mkv3copy.py; edit the generator.
*
*   sh hardware/video3/bench/run-v3copy.sh
*
* plan 6.  Bitmap mode makes VRAM observable: a byte IS a palette index IS a
* pixel, so a copy that puts a byte in the wrong place is visible.  The list
* covers aligned and unaligned columns, both directions in both axes, and four
* overlapping copies - which is where a direction bit that walks the wrong way
* destroys its own source.
*******************************************************************************

VCTRL   EQU     $FF60
VSCROLL EQU     $FF61
WPTR0   EQU     $FF68
WPTR1   EQU     $FF69
WPTR2   EQU     $FF6A
WADV    EQU     $FF6B
VDATA   EQU     $FF6C
VSTAT   EQU     $FF6D
PIDXL   EQU     $FF6E
PIDXH   EQU     $FF6F
PDATL   EQU     $FF70
PDATH   EQU     $FF71
CPTR0   EQU     $FF72
CPTR1   EQU     $FF73
CPTR2   EQU     $FF74
CWIDTH  EQU     $FF75
CHEIGHT EQU     $FF76
CCTRL   EQU     $FF77
SIMPORT EQU     $FF2F

row     EQU     $C100
seed    EQU     $C102

        ORG     $8000
        FCC     "6309"
        JMP     start

        SETDP   $FF
start   orcc    #$50
        lds     #$E000
        lda     #$FF
        tfr     a,dp
        clr     <VCTRL          display off, bitmap, WMODE 00
        clr     <WADV
        clr     <VSCROLL
        clr     <VSCROLL+1

* --- sub-palette 0: entry i = i * $0101, so a pixel's value is recoverable
        clr     <PIDXH
        clr     <PIDXL
        clrb
pal1    stb     <PDATL
        stb     <PDATH
        incb
        bne     pal1

* --- the pattern: VRAM[r][c] = (r * 7 + c * 3) & $FF
        clr     row
        clr     row+1
fr1     ldd     row
        lslb
        rola
        lslb
        rola                    D = row * 4 -> WPTR1:WPTR0 is row * 1024
        clr     <WPTR0
        stb     <WPTR1
        sta     <WPTR2          WPTR = row * 1024, so the row starts at WPTR1
        ldb     row+1
        lda     #7
        mul                     B = row * 7, low byte
        stb     seed
        ldy     #640
fc1     lda     seed
        sta     <VDATA
        adda    #3
        sta     seed
        leay    -1,y
        bne     fc1
        ldd     row
        addd    #1
        std     row
        cmpd    #200
        blo     fr1

* --- the keyed shape into off-screen rows: its holes are index 0
        ldx     #shape
        ldd     #260
        std     row
shr1    ldd     row
        lslb
        rola
        lslb
        rola
        anda    #7
        sta     <WPTR2
        stb     <WPTR1
        lda     #$00
        sta     <WPTR0
        ldb     #16
shc1    lda     ,x+
        sta     <VDATA
        decb
        bne     shc1
        ldd     row
        addd    #1
        std     row
        cmpd    #276
        blo     shr1

* --- the copies
* vertical only, non-overlapping
        lda     #$00
        sta     <CPTR2
        lda     #$00
        sta     <CPTR1
        lda     #$00
        sta     <CPTR0
        lda     #$01
        sta     <WPTR2
        lda     #$90
        sta     <WPTR1
        lda     #$00
        sta     <WPTR0
        lda     #$40
        sta     <CWIDTH
        lda     #$10
        sta     <CHEIGHT
        lda     #$01
        sta     <CCTRL          GO
cw00    lda     <VSTAT
        bmi     cw00
* horizontal, columns congruent mod 4
        lda     #$00
        sta     <CPTR2
        lda     #$50
        sta     <CPTR1
        lda     #$00
        sta     <CPTR0
        lda     #$00
        sta     <WPTR2
        lda     #$70
        sta     <WPTR1
        lda     #$40
        sta     <WPTR0
        lda     #$20
        sta     <CWIDTH
        lda     #$08
        sta     <CHEIGHT
        lda     #$01
        sta     <CCTRL          GO
cw01    lda     <VSTAT
        bmi     cw01
* horizontal, NOT congruent mod 4
        lda     #$00
        sta     <CPTR2
        lda     #$A0
        sta     <CPTR1
        lda     #$01
        sta     <CPTR0
        lda     #$00
        sta     <WPTR2
        lda     #$C0
        sta     <WPTR1
        lda     #$42
        sta     <WPTR0
        lda     #$21
        sta     <CWIDTH
        lda     #$08
        sta     <CHEIGHT
        lda     #$01
        sta     <CCTRL          GO
cw02    lda     <VSTAT
        bmi     cw02
* overlapping scroll UP, rows ascend
        lda     #$00
        sta     <CPTR2
        lda     #$F0
        sta     <CPTR1
        lda     #$00
        sta     <CPTR0
        lda     #$00
        sta     <WPTR2
        lda     #$D0
        sta     <WPTR1
        lda     #$00
        sta     <WPTR0
        lda     #$80
        sta     <CWIDTH
        lda     #$20
        sta     <CHEIGHT
        lda     #$01
        sta     <CCTRL          GO
cw03    lda     <VSTAT
        bmi     cw03
* scroll DOWN, pass 1: to scratch
        lda     #$01
        sta     <CPTR2
        lda     #$E0
        sta     <CPTR1
        lda     #$00
        sta     <CPTR0
        lda     #$04
        sta     <WPTR2
        lda     #$B0
        sta     <WPTR1
        lda     #$00
        sta     <WPTR0
        lda     #$80
        sta     <CWIDTH
        lda     #$20
        sta     <CHEIGHT
        lda     #$01
        sta     <CCTRL          GO
cw04    lda     <VSTAT
        bmi     cw04
* scroll DOWN, pass 2: back, 8 lower
        lda     #$04
        sta     <CPTR2
        lda     #$B0
        sta     <CPTR1
        lda     #$00
        sta     <CPTR0
        lda     #$02
        sta     <WPTR2
        lda     #$00
        sta     <WPTR1
        lda     #$00
        sta     <WPTR0
        lda     #$80
        sta     <CWIDTH
        lda     #$20
        sta     <CHEIGHT
        lda     #$01
        sta     <CCTRL          GO
cw05    lda     <VSTAT
        bmi     cw05
* shift RIGHT, pass 1: to scratch
        lda     #$02
        sta     <CPTR2
        lda     #$80
        sta     <CPTR1
        lda     #$00
        sta     <CPTR0
        lda     #$05
        sta     <WPTR2
        lda     #$00
        sta     <WPTR1
        lda     #$00
        sta     <WPTR0
        lda     #$40
        sta     <CWIDTH
        lda     #$08
        sta     <CHEIGHT
        lda     #$01
        sta     <CCTRL          GO
cw06    lda     <VSTAT
        bmi     cw06
* shift RIGHT, pass 2: back, 8 right
        lda     #$05
        sta     <CPTR2
        lda     #$00
        sta     <CPTR1
        lda     #$00
        sta     <CPTR0
        lda     #$02
        sta     <WPTR2
        lda     #$80
        sta     <WPTR1
        lda     #$08
        sta     <WPTR0
        lda     #$40
        sta     <CWIDTH
        lda     #$08
        sta     <CHEIGHT
        lda     #$01
        sta     <CCTRL          GO
cw07    lda     <VSTAT
        bmi     cw07
* overlapping LEFT, columns ascend
        lda     #$02
        sta     <CPTR2
        lda     #$D0
        sta     <CPTR1
        lda     #$08
        sta     <CPTR0
        lda     #$02
        sta     <WPTR2
        lda     #$D0
        sta     <WPTR1
        lda     #$00
        sta     <WPTR0
        lda     #$40
        sta     <CWIDTH
        lda     #$08
        sta     <CHEIGHT
        lda     #$01
        sta     <CCTRL          GO
cw08    lda     <VSTAT
        bmi     cw08
* one row, one byte
        lda     #$01
        sta     <CPTR2
        lda     #$8E
        sta     <CPTR1
        lda     #$7F
        sta     <CPTR0
        lda     #$01
        sta     <WPTR2
        lda     #$89
        sta     <WPTR1
        lda     #$40
        sta     <WPTR0
        lda     #$01
        sta     <CWIDTH
        lda     #$01
        sta     <CHEIGHT
        lda     #$01
        sta     <CCTRL          GO
cw09    lda     <VSTAT
        bmi     cw09
        lda     #$30            WMODE 11 arms the key
        sta     <VCTRL
* KEYED: the shape over the pattern
        lda     #$04
        sta     <CPTR2
        lda     #$10
        sta     <CPTR1
        lda     #$00
        sta     <CPTR0
        lda     #$02
        sta     <WPTR2
        lda     #$30
        sta     <WPTR1
        lda     #$C8
        sta     <WPTR0
        lda     #$10
        sta     <CWIDTH
        lda     #$10
        sta     <CHEIGHT
        lda     #$01
        sta     <CCTRL          GO
cw10    lda     <VSTAT
        bmi     cw10
        clr     <VCTRL          and the key is off again
* the SAME shape, NOT keyed
        lda     #$04
        sta     <CPTR2
        lda     #$10
        sta     <CPTR1
        lda     #$00
        sta     <CPTR0
        lda     #$02
        sta     <WPTR2
        lda     #$30
        sta     <WPTR1
        lda     #$F0
        sta     <WPTR0
        lda     #$10
        sta     <CWIDTH
        lda     #$10
        sta     <CHEIGHT
        lda     #$01
        sta     <CCTRL          GO
cw11    lda     <VSTAT
        bmi     cw11
        lda     #$30            WMODE 11 arms the key
        sta     <VCTRL
* KEYED at column 401, 1 mod 4
        lda     #$04
        sta     <CPTR2
        lda     #$10
        sta     <CPTR1
        lda     #$00
        sta     <CPTR0
        lda     #$02
        sta     <WPTR2
        lda     #$C9
        sta     <WPTR1
        lda     #$91
        sta     <WPTR0
        lda     #$10
        sta     <CWIDTH
        lda     #$10
        sta     <CHEIGHT
        lda     #$01
        sta     <CCTRL          GO
cw12    lda     <VSTAT
        bmi     cw12
        clr     <VCTRL          and the key is off again
        lda     #$30            WMODE 11 arms the key
        sta     <VCTRL
* KEYED from the pattern: one hole
        lda     #$00
        sta     <CPTR2
        lda     #$00
        sta     <CPTR1
        lda     #$00
        sta     <CPTR0
        lda     #$02
        sta     <WPTR2
        lda     #$A9
        sta     <WPTR1
        lda     #$2C
        sta     <WPTR0
        lda     #$10
        sta     <CWIDTH
        lda     #$10
        sta     <CHEIGHT
        lda     #$01
        sta     <CCTRL          GO
cw13    lda     <VSTAT
        bmi     cw13
        clr     <VCTRL          and the key is off again

* --- bitmap mode, 640x200, display on
        lda     #$80            b7 display, MODE 00 bitmap, VMODE 00
        sta     <VCTRL
        lda     #$A0
        sta     SIMPORT
done    bra     done

* the shape, row by row: 0 is the key and the ink never is
shape
        FCB     $00,$02,$03,$04,$05,$06,$07,$08,$09,$0A,$0B,$0C,$0D,$0E,$0F,$00
        FCB     $11,$00,$13,$14,$15,$16,$17,$18,$19,$1A,$1B,$1C,$1D,$1E,$00,$20
        FCB     $21,$22,$00,$24,$25,$26,$27,$28,$29,$2A,$2B,$2C,$2D,$00,$2F,$30
        FCB     $31,$32,$33,$00,$35,$36,$37,$38,$39,$3A,$3B,$3C,$00,$3E,$3F,$40
        FCB     $41,$42,$43,$44,$00,$00,$00,$00,$00,$00,$00,$00,$4D,$4E,$4F,$50
        FCB     $51,$52,$53,$54,$00,$00,$00,$00,$00,$00,$00,$00,$5D,$5E,$5F,$60
        FCB     $61,$62,$63,$64,$00,$00,$00,$00,$00,$00,$00,$00,$6D,$6E,$6F,$70
        FCB     $71,$72,$73,$74,$00,$00,$00,$00,$00,$00,$00,$00,$7D,$7E,$7F,$80
        FCB     $81,$82,$83,$84,$00,$00,$00,$00,$00,$00,$00,$00,$8D,$8E,$8F,$90
        FCB     $91,$92,$93,$94,$00,$00,$00,$00,$00,$00,$00,$00,$9D,$9E,$9F,$A0
        FCB     $A1,$A2,$A3,$A4,$00,$00,$00,$00,$00,$00,$00,$00,$AD,$AE,$AF,$B0
        FCB     $B1,$B2,$B3,$B4,$00,$00,$00,$00,$00,$00,$00,$00,$BD,$BE,$BF,$C0
        FCB     $C1,$C2,$C3,$00,$C5,$C6,$C7,$C8,$C9,$CA,$CB,$CC,$00,$CE,$CF,$D0
        FCB     $D1,$D2,$00,$D4,$D5,$D6,$D7,$D8,$D9,$DA,$DB,$DC,$DD,$00,$DF,$E0
        FCB     $E1,$00,$E3,$E4,$E5,$E6,$E7,$E8,$E9,$EA,$EB,$EC,$ED,$EE,$00,$F0
        FCB     $00,$F2,$F3,$F4,$F5,$F6,$F7,$F8,$F9,$FA,$FB,$FC,$FD,$FE,$FF,$00
        END
